var a={en:`A small academy needs courses, enrollment, billing and instructor schedules. Two developers want one deployment with strongly separated business responsibilities.`,ua:`Невеликій академії потрібні курси, записи, рахунки й розклади викладачів. Двоє розробників хочуть один застосунок із чітко відокремленими бізнес-відповідальностями.`};var s={en:[`Create module boundaries and internal contracts on a blank canvas.`,`Identify owners of student, enrollment and invoice data.`,`Draw transactional enrollment and asynchronous notification paths.`],ua:[`Створи межі модулів та внутрішні контракти на порожньому полотні.`,`Визнач власників даних студента, запису й рахунку.`,`Намалюй транзакційний запис та асинхронні сповіщення.`]};var t=[{en:`One deployment is kept with explicit module interfaces.`,ua:`Збережено одне розгортання з явними інтерфейсами модулів.`},{en:`No module directly modifies another module’s private records.`,ua:`Модулі не змінюють чужі приватні записи напряму.`}];var o={scenario:a,tasks:s,checks:t};export{t as checks,o as default,a as scenario,s as tasks};